<script setup lang="ts">
import { onMounted, onUnmounted, reactive, ref } from 'vue'
import { guardarLecturaMacro, historialMacromedidor, listarMacromedidores, type LecturaMacro, type Macromedidor } from '../services/macromedidores'
const records=ref<Macromedidor[]>([]),history=ref<LecturaMacro[]>([]),type=ref<'fisico'|'virtual'>('fisico'),query=ref(''),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),current=ref<Macromedidor|null>(null),reading=ref<number|null>(null),file=ref<File|null>(null),preview=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),summary=reactive({fisicos:0,virtuales:0,con_lectura_hoy:0})
async function load(target=1){loading.value=true;error.value='';try{const r=await listarMacromedidores(type.value,query.value,target);records.value=r.data;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total;Object.assign(summary,r.resumen)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function switchType(value:'fisico'|'virtual'){type.value=value;query.value='';page.value=1;await load()}
async function open(item:Macromedidor){current.value=item;reading.value=null;clearFile();modal.value=true;loading.value=true;try{const r=await historialMacromedidor(item.id);history.value=r.data}catch(e){error.value=message(e)}finally{loading.value=false}}
function selected(event:Event){const selected=(event.target as HTMLInputElement).files?.[0]??null;if(!selected)return;if(!selected.type.startsWith('image/')){error.value='Seleccione una imagen válida.';return}clearFile();file.value=selected;preview.value=URL.createObjectURL(selected)}function clearFile(){if(preview.value)URL.revokeObjectURL(preview.value);file.value=null;preview.value=''}
async function save(){if(!current.value||reading.value===null||reading.value<0){error.value='Ingrese una lectura numérica válida.';return}if(current.value.tipo==='fisico'&&!file.value){error.value='Adjunte la captura del macromedidor físico.';return}saving.value=true;try{await guardarLecturaMacro(current.value,reading.value,file.value);success.value=`Lectura registrada para ${current.value.nombre}.`;const r=await historialMacromedidor(current.value.id);history.value=r.data;reading.value=null;clearFile();await load(page.value)}catch(e){error.value=message(e)}finally{saving.value=false}}
const projected=()=>reading.value===null?0:(reading.value*3.6)*24;const format=(value:number|null)=>value===null?'—':new Intl.NumberFormat('es-PE',{maximumFractionDigits:2}).format(value);const clear=()=>{query.value='';load(1)};const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.'
onMounted(()=>load());onUnmounted(clearFile)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Operaciones / Producción / Macromedidores</nav><header class="hero"><div class="mark">MM</div><div><small>DANA · PRODUCCIÓN</small><h1>Macromedidores</h1><p>Consulta los puntos de medición y registra lecturas de producción.</p></div></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="summary"><article><small>MACROMEDIDORES FÍSICOS</small><b>{{summary.fisicos}}</b></article><article><small>MACROMEDIDORES VIRTUALES</small><b>{{summary.virtuales}}</b></article><article><small>CON LECTURA HOY</small><b>{{summary.con_lectura_hoy}}</b></article></section><section class="toolbar"><div class="tabs"><button :class="{active:type==='fisico'}" @click="switchType('fisico')">Físicos</button><button :class="{active:type==='virtual'}" @click="switchType('virtual')">Virtuales</button></div><form @submit.prevent="load(1)"><input v-model.trim="query" placeholder="Nombre, sistema o distrito"><button>Buscar</button><button v-if="query" type="button" class="soft" @click="clear">Limpiar</button></form></section><div v-if="loading&&!modal" class="empty">Cargando macromedidores…</div><div v-else-if="!records.length" class="empty">No se encontraron macromedidores {{type==='fisico'?'físicos':'virtuales'}}.</div><section v-else class="cards"><article v-for="item in records" :key="item.id" :class="item.tipo"><header><div class="meter">◉</div><div><small>{{item.tipo==='fisico'?'MEDICIÓN DIRECTA':'CÁLCULO VIRTUAL'}}</small><h2>{{item.nombre}}</h2></div><span>{{item.condicion}}</span></header><dl><div><dt>Distrito</dt><dd>{{item.distrito}}</dd></div><div><dt>Sistema</dt><dd>{{item.sistema}}</dd></div><div><dt>Última lectura</dt><dd><strong>{{format(item.ultima_lectura)}} {{item.unidad}}</strong></dd></div><div><dt>Fecha de lectura</dt><dd>{{item.ultima_fecha||'Sin registros'}}</dd></div><div><dt>Historial</dt><dd>{{item.lecturas_count}} lectura(s)</dd></div></dl><button @click="open(item)">Tomar lectura</button></article></section><footer v-if="lastPage>1" class="pager"><button :disabled="page===1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}} · {{total}} registros</span><button :disabled="page===lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><section class="dialog"><header><div><small>{{current?.distrito}} · {{current?.sistema}}</small><h2>{{current?.nombre}}</h2></div><button @click="modal=false">×</button></header><div class="body"><form @submit.prevent="save"><p>{{current?.tipo==='fisico'?'Registre el valor mostrado por el equipo y adjunte una fotografía.':'Registre el caudal instantáneo para calcular el volumen diario.'}}</p><label>{{current?.tipo==='fisico'?'Lectura del medidor':'Caudal (L/s)'}} *<input v-model.number="reading" type="number" min="0" step="0.001"></label><div v-if="current?.tipo==='virtual'" class="formula"><small>VOLUMEN DIARIO CALCULADO</small><b>{{format(projected())}} m³/día</b><span>(caudal × 3.6) × 24</span></div><label v-else class="drop"><input type="file" accept="image/*" capture="environment" @change="selected"><template v-if="!preview"><b>Adjuntar captura del macromedidor</b><span>Seleccionar fotografía o usar cámara</span></template><img v-else :src="preview" alt="Captura"></label><button class="save" :disabled="saving">{{saving?'Guardando…':'Registrar lectura'}}</button></form><section class="history"><h3>Últimos 10 registros</h3><div v-if="loading">Cargando historial…</div><table v-else><thead><tr><th>Fecha</th><th>Lectura</th><th>Usuario</th><th></th></tr></thead><tbody><tr v-for="row in history" :key="row.id"><td>{{row.fecha_hora}}</td><td><b>{{format(row.lectura)}}</b></td><td>{{row.usuario}}</td><td><a v-if="row.imagen_url" :href="row.imagen_url" target="_blank">Ver</a></td></tr><tr v-if="!history.length"><td colspan="4">No hay registros.</td></tr></tbody></table></section></div></section></div></div></template>
